INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Intrusion Detection System (IDS) eine technische Maßnahme zur IT-Sicherheit?', 2, '[{"text": "Ja", "correct": true, "because": "Erkennt Bedrohungen"}, {"text": "Nein", "correct": false, "because": "Es ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt ein IDS?', 3, '[{"text": "Erkennung unbefugter Aktivitäten im Netzwerk", "correct": true, "because": "Überwacht Anomalien"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Netzwerkgeschwindigkeit erhöhen", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein IDS überwacht den Netzwerkverkehr. b) Es blockiert Angriffe automatisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, IPS blockiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von IDS gibt es?', 4, '[{"text": "Netzwerkbasiertes IDS (NIDS)", "correct": true, "because": "Überwacht Netzwerk"}, {"text": "Unklare Systeme", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Hostbasiertes IDS (HIDS)", "correct": true, "because": "Überwacht Geräte"}, {"text": "Signaturbasiertes IDS", "correct": true, "because": "Erkennt bekannte Muster"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Netzwerk ohne IDS sicher sein?', 2, '[{"text": "Ja", "correct": true, "because": "Andere Maßnahmen möglich"}, {"text": "Nein", "correct": false, "because": "Ergänzt Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ein IDS in der IT-Sicherheit?', 3, '[{"text": "Früherkennung von Sicherheitsvorfällen", "correct": true, "because": "Warnt vor Angriffen"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Funktion"}, {"text": "Netzwerk trennen", "correct": false, "because": "IPS-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein IDS nur für große Netzwerke relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Netzwerke"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein signaturbasiertes IDS?', 3, '[{"text": "Erkennt bekannte Angriffsmuster", "correct": true, "because": "Vergleicht Signaturen"}, {"text": "Blockiert Angriffe", "correct": false, "because": "IPS-Funktion"}, {"text": "Daten löschen", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein IDS generiert Alarme bei Anomalien. b) Es schützt direkt vor Angriffen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, nur Erkennung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne IDS in einem Netzwerk?', 3, '[{"text": "Angriffe bleiben unerkannt", "correct": true, "because": "Keine Überwachung"}, {"text": "Netzwerk wird schneller", "correct": false, "because": "Unsinn"}, {"text": "Daten sicherer", "correct": false, "because": "Gegenteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IDS ohne Firewall arbeiten?', 2, '[{"text": "Ja", "correct": true, "because": "Unabhängig möglich"}, {"text": "Nein", "correct": false, "because": "Ergänzt Firewall"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine IDS-Funktion?', 3, '[{"text": "Alarm bei ungewöhnlichem Datenverkehr", "correct": true, "because": "Konkret und real"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Netzwerk trennen", "correct": false, "because": "IPS-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein IDS nur für externe Bedrohungen relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch interne Bedrohungen"}, {"text": "Ja", "correct": false, "because": "Umfassender Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein IDS?', 4, '[{"text": "Überwachung", "correct": true, "because": "Erkennt Aktivitäten"}, {"text": "Unklare Daten", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Alarmfunktion", "correct": true, "because": "Warnt bei Bedrohungen"}, {"text": "Anomalieerkennung", "correct": true, "because": "Erkennt Abweichungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein IDS automatisch reagieren?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Erkennung, keine Abwehr"}, {"text": "Ja", "correct": false, "because": "IPS reagiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ein hostbasiertes IDS?', 3, '[{"text": "Überwacht einzelne Geräte", "correct": true, "because": "Fokus auf Host"}, {"text": "Blockiert Netzwerkzugriffe", "correct": false, "because": "IPS-Funktion"}, {"text": "Daten löschen", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IDS ohne Protokollanalyse arbeiten?', 2, '[{"text": "Ja", "correct": true, "because": "Anomalieerkennung möglich"}, {"text": "Nein", "correct": false, "because": "Analyse ergänzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinträchtigt ein IDS?', 3, '[{"text": "Hohe Fehlalarmrate", "correct": true, "because": "Reduziert Effektivität"}, {"text": "Schnelles Netzwerk", "correct": false, "because": "Kein direkter Einfluss"}, {"text": "Gute Passwörter", "correct": false, "because": "Unterstützt Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein IDS erkennt Angriffe frühzeitig. b) Es ersetzt eine Firewall.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, ergänzt Firewall"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen eines IDS?', 3, '[{"text": "Frühwarnsystem für Bedrohungen", "correct": true, "because": "Fördert Sicherheit"}, {"text": "Maximale Unsicherheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Erkennung", "correct": false, "because": "Fördert Überwachung"}]');